import copy
import sys
sys.setrecursionlimit(1 << 20)

N, H, W = map(int, input().split())
AB = list()

for _ in range(N):
    a, b = map(int, input().split())
    AB.append([a, b])
global ans
ans = False
C = [[True for _ in range(W)] for i in range(H)]

def dfs(x, y, rem, masu):
    global ans
    if all(all(row) for row in masu):
        ans = True
        return
    if y == W:
        for i in range(H):
            for j in range(W):
                if not masu[i][j]:
                    x, y = i, j
                    break
            else:
                continue
            break

    for i in range(len(rem)):
        piece = rem[i]
        for _ in range(2):
            piece = piece[::-1]
            if x + piece[0] <= H and y + piece[1] <= W:
                R_tmp = rem[:i] + rem[i+1:]
                M_tmp = copy.deepcopy(masu)
                flag = True
                for a in range(x, x + piece[0]):
                    for b in range(y, y + piece[1]):
                        if M_tmp[a][b]:
                            flag = False
                        M_tmp[a][b] = True
                if flag:
                    dfs(x, y + piece[1], R_tmp, M_tmp)

for bits in product([0, 1], repeat=N):
    bits = list(bits)
    item = [AB[i] for i in range(N) if bits[i]]
    masu = [[False for _ in range(W)] for j in range(H)]
